sysdrills/13-search-and-indexing/02-post.solution:
export function mergeOps(listLengths) {
  return listLengths.reduce((sum, n) => sum + n, 0);
}

export function maxPossibleHits(listLengths) {
  return Math.min(...listLengths);
}

export function skipProbes(listLengths) {
  return Math.min(...listLengths) * (listLengths.length - 1);
}

